// Google Nano Banana: generate an image, then hand its path to the next step.
// Runs in Layla's QuickJS `eval` runtime (fetch + the Layla SDK as `layla`).
// Returns the image path relative to the character workspace, which display-image resolves.

const API_KEY = 'PUT YOUR API KEY HERE';
// The prompt is pasted in by Layla before this code runs. A backtick or `${` in it would end the literal.
const PROMPT = String.raw`{{match$1}}`.trim();

const MODEL_ID = 'gemini-3-pro-image';
const API_METHOD = 'streamGenerateContent';
const API_URL = `https://generativelanguage.googleapis.com/v1beta/models/${MODEL_ID}:${API_METHOD}`;
const TIMEOUT_MS = 60000;

async function generateImage(prompt) {
  if (!prompt) throw new Error('The stable diffusion prompt was empty.');
  if (!API_KEY || API_KEY === 'PUT YOUR API KEY HERE') throw new Error('Set API_KEY in this agent first.');

  // Empty values make the API answer 400, so only send the settings that are set.
  const imageConfig = { imageSize: '1K' };

  const payload = {
    contents: [{ role: 'user', parts: [{ text: prompt }] }],
    generationConfig: {
      responseModalities: ['IMAGE', 'TEXT'],
      imageConfig,
    },
    tools: [{ googleSearch: {} }],
  };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  let response;
  let body;
  try {
    response = await fetch(API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': API_KEY },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    body = await response.text();
  } catch (error) {
    if (controller.signal.aborted) throw new Error(`Image generation timed out after ${TIMEOUT_MS / 1000} s.`);
    throw new Error(`Image generation request failed: ${error.message}`);
  } finally {
    clearTimeout(timer);
  }

  if (!response.ok) {
    throw new Error(`HTTP error ${response.status} ${response.statusText}. Response body: ${body.slice(0, 500)}`);
  }

  // streamGenerateContent answers with a JSON array of chunks.
  const data = JSON.parse(body);
  const chunks = Array.isArray(data) ? data : [data];

  // Take the first image and ignore any text parts.
  for (const chunk of chunks) {
    for (const candidate of chunk.candidates || []) {
      for (const part of (candidate.content && candidate.content.parts) || []) {
        const inline = part.inlineData;
        if (!inline || !inline.data || !String(inline.mimeType || '').startsWith('image/')) continue;

        const extension = inline.mimeType.split('/').pop().replace(/[^a-z0-9]/gi, '') || 'png';
        const id = Math.random().toString(16).slice(2, 10).padEnd(8, '0');
        const path = `generated-images/output_image_${id}.${extension}`;

        // The API already returns base64, so it goes to the workspace as is.
        await layla.utils.saveFile(path, inline.data);
        return path;
      }
    }
  }

  const keys = chunks.length && typeof chunks[0] === 'object' ? Object.keys(chunks[0]).join(', ') : 'Unknown error';
  throw new Error(`No image was found in the response. Full API Response Keys: ${keys}`);
}

generateImage(PROMPT);
